package integration

import (
	"context"
	"strings"

	"cosmicforge/logistics/services/payment-wallet-service/internal/features/finance/models"
	"cosmicforge/logistics/services/payment-wallet-service/internal/features/finance/usecases"
	walletclients "cosmicforge/logistics/services/payment-wallet-service/internal/features/wallets/clients"
)

// PaystackGateway executes and reads back payouts/refunds. References are
// generated by Wallet before the request, making retries safe at the provider.
type PaystackGateway struct {
	Client walletclients.HTTPPaystackClient
}

func (g PaystackGateway) Configured() bool { return g.Client.SecretKey != "" && g.Client.BaseURL != "" }

func (g PaystackGateway) ExecuteSettlement(ctx context.Context, batch models.SettlementBatch,
	item models.SettlementItem) (usecases.ExternalOutcome, error) {
	result, err := g.Client.InitiateTransfer(ctx, walletclients.InitiateTransferRequest{
		AmountKobo: item.AmountMinor, RecipientCode: batch.BeneficiaryReference,
		Reason: "settlement " + batch.ID, Reference: item.IdempotencyKey})
	if err != nil {
		return usecases.ExternalOutcome{Kind: usecases.OutcomeUnknown, ExternalReference: item.IdempotencyKey, SafeErrorCode: "provider_unavailable"}, err
	}
	return classify(result.Status, result.Reference), nil
}

func (g PaystackGateway) ReadSettlement(ctx context.Context, item models.SettlementItem) (usecases.ExternalOutcome, error) {
	ref := item.ExternalReference
	if ref == "" {
		ref = item.IdempotencyKey
	}
	result, err := g.Client.VerifyTransfer(ctx, ref)
	if err != nil {
		return usecases.ExternalOutcome{Kind: usecases.OutcomeUnknown, ExternalReference: ref, SafeErrorCode: "readback_unavailable"}, err
	}
	return classify(result.Status, result.Reference), nil
}

func (g PaystackGateway) ExecuteRefund(ctx context.Context, refund models.Refund) (usecases.ExternalOutcome, error) {
	result, err := g.Client.CreateRefund(ctx, walletclients.CreateRefundRequest{TransactionReference: refund.OriginalReference, AmountKobo: refund.AmountMinor, Currency: refund.Currency, MerchantNote: refund.IdempotencyKey})
	if err != nil {
		return usecases.ExternalOutcome{Kind: usecases.OutcomeUnknown, ExternalReference: refund.IdempotencyKey, SafeErrorCode: "provider_unavailable"}, err
	}
	return classify(result.Status, result.Reference), nil
}

func (g PaystackGateway) ReadRefund(ctx context.Context, refund models.Refund) (usecases.ExternalOutcome, error) {
	ref := refund.ExternalReference
	if ref == "" {
		ref = refund.IdempotencyKey
	}
	result, err := g.Client.VerifyRefund(ctx, ref)
	if err != nil {
		return usecases.ExternalOutcome{Kind: usecases.OutcomeUnknown, ExternalReference: ref, SafeErrorCode: "readback_unavailable"}, err
	}
	return classify(result.Status, result.Reference), nil
}

// ExecuteReversal performs the external half of a reversal.
//
// A reversal that carries no external operation reference is a pure ledger
// correction: nothing left Wallet, so nothing has to be recalled and the
// compensating journal may be posted immediately. Where an external payout is
// being reversed, the provider refund is issued under the reversal's own
// idempotency key so a retry cannot double-refund.
func (g PaystackGateway) ExecuteReversal(ctx context.Context, reversal models.Reversal) (usecases.ExternalOutcome, error) {
	if reversal.OriginalReference == "" {
		return usecases.ExternalOutcome{Kind: usecases.OutcomeSucceeded}, nil
	}
	result, err := g.Client.CreateRefund(ctx, walletclients.CreateRefundRequest{
		TransactionReference: reversal.OriginalReference, AmountKobo: reversal.AmountMinor,
		Currency: reversal.Currency, MerchantNote: reversal.IdempotencyKey})
	if err != nil {
		return usecases.ExternalOutcome{Kind: usecases.OutcomeUnknown,
			ExternalReference: reversal.IdempotencyKey, SafeErrorCode: "provider_unavailable"}, err
	}
	return classify(result.Status, result.Reference), nil
}

// ReadReversal resolves an ambiguous reversal by asking the provider what
// actually happened, never by issuing the operation again.
func (g PaystackGateway) ReadReversal(ctx context.Context, reversal models.Reversal) (usecases.ExternalOutcome, error) {
	if reversal.OriginalReference == "" {
		return usecases.ExternalOutcome{Kind: usecases.OutcomeSucceeded}, nil
	}
	ref := reversal.ExternalOperationReference
	if ref == "" {
		ref = reversal.IdempotencyKey
	}
	result, err := g.Client.VerifyRefund(ctx, ref)
	if err != nil {
		return usecases.ExternalOutcome{Kind: usecases.OutcomeUnknown,
			ExternalReference: ref, SafeErrorCode: "readback_unavailable"}, err
	}
	return classify(result.Status, result.Reference), nil
}

func classify(status, reference string) usecases.ExternalOutcome {
	switch strings.ToLower(strings.TrimSpace(status)) {
	case "success", "successful", "processed", "completed":
		return usecases.ExternalOutcome{Kind: usecases.OutcomeSucceeded, ExternalReference: reference}
	case "failed", "rejected", "cancelled":
		return usecases.ExternalOutcome{Kind: usecases.OutcomePermanent, ExternalReference: reference, SafeErrorCode: "provider_rejected"}
	case "pending", "processing", "queued", "otp":
		return usecases.ExternalOutcome{Kind: usecases.OutcomeUnknown, ExternalReference: reference, SafeErrorCode: "provider_pending"}
	default:
		return usecases.ExternalOutcome{Kind: usecases.OutcomeUnknown, ExternalReference: reference, SafeErrorCode: "provider_unknown"}
	}
}

var _ usecases.MoneyGateway = PaystackGateway{}
